-- RC50.82 - Central de Qualidade e Consistência. Idempotente e sem operação destrutiva.
do $$ begin
  if to_regclass('sigov.tenant') is null then raise exception 'Schema obrigatório ausente: sigov.tenant'; end if;
  if to_regclass('sigov.entidade') is null then raise exception 'Schema obrigatório ausente: sigov.entidade'; end if;
end $$;

create table if not exists sigov.qualidade_checklist (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null,
 modulo varchar(80) not null, titulo varchar(200) not null, status varchar(20) not null default 'ATIVO',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_checklist_status check(status in ('ATIVO','CONCLUIDO','ARQUIVADO')));
create table if not exists sigov.qualidade_checklist_item (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, checklist_id bigint not null references sigov.qualidade_checklist(id),
 modulo varchar(80) not null, referencia varchar(240) not null, status varchar(20) not null default 'PENDENTE', evidencia text,
 validado_em timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_checklist_item_status check(status in ('PENDENTE','CONFORME','NAO_CONFORME','NAO_APLICAVEL')));
create table if not exists sigov.qualidade_inconsistencia (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, modulo varchar(80) not null, titulo varchar(200) not null,
 severidade varchar(10) not null, status varchar(32) not null default 'ABERTA', responsavel_usuario_id bigint not null, evidencia text not null, tela varchar(160), rota varchar(240),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_inconsistencia_severidade check(severidade in ('BAIXA','MEDIA','ALTA','CRITICA')),
 constraint ck_qualidade_inconsistencia_status check(status in ('ABERTA','EM_ANALISE','CORRIGIDA','IGNORADA_COM_JUSTIFICATIVA')));
create table if not exists sigov.qualidade_inconsistencia_historico (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, inconsistencia_id bigint not null references sigov.qualidade_inconsistencia(id),
 status_novo varchar(32) not null, justificativa text not null, created_at timestamptz not null default now(), created_by bigint not null,
 constraint ck_qualidade_historico_status check(status_novo in ('ABERTA','EM_ANALISE','CORRIGIDA','IGNORADA_COM_JUSTIFICATIVA')),
 constraint ck_qualidade_historico_justificativa check(length(trim(justificativa))>=10));

create table if not exists sigov.qualidade_smoke_rota (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, modulo varchar(80) not null, referencia varchar(240) not null,
 metodo varchar(10) not null default 'GET', status varchar(20) not null default 'PENDENTE', detalhe text, validado_em timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_rota_metodo check(metodo in ('GET','POST','PUT','PATCH','DELETE')), constraint ck_qualidade_rota_status check(status in ('PENDENTE','CONFORME','FALHA','BLOQUEADO')));

create table if not exists sigov.qualidade_validacao_sql (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, modulo varchar(80) not null, referencia varchar(240) not null,
 tipo varchar(20) not null default 'MIGRATION', status varchar(20) not null default 'PENDENTE', detalhe text, checksum varchar(64), validado_em timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_sql_tipo check(tipo in ('MIGRATION','BASELINE','FUNCAO','VIEW','SEED')), constraint ck_qualidade_sql_status check(status in ('PENDENTE','CONFORME','FALHA','BLOQUEADO')));
create table if not exists sigov.qualidade_validacao_formulario (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, modulo varchar(80) not null, referencia varchar(240) not null,
 tipo varchar(24) not null default 'FORMULARIO', status varchar(20) not null default 'PENDENTE', detalhe text, validado_em timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_form_tipo check(tipo in ('FORMULARIO','ANTIFORGERY','VALIDACAO','ACESSIBILIDADE')), constraint ck_qualidade_form_status check(status in ('PENDENTE','CONFORME','FALHA','BLOQUEADO')));
create table if not exists sigov.qualidade_validacao_permissao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, modulo varchar(80) not null, referencia varchar(240) not null,
 tipo varchar(24) not null default 'AUTORIZACAO', status varchar(20) not null default 'PENDENTE', detalhe text, validado_em timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_permissao_tipo check(tipo in ('AUTORIZACAO','EXPORTACAO','DADO_SENSIVEL','AUDITORIA')), constraint ck_qualidade_permissao_status check(status in ('PENDENTE','CONFORME','FALHA','BLOQUEADO')));
create table if not exists sigov.qualidade_validacao_integracao (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, modulo varchar(80) not null, referencia varchar(240) not null,
 tipo varchar(20) not null default 'OUTBOX', status varchar(20) not null default 'PENDENTE', detalhe text, validado_em timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint not null, updated_by bigint not null,
 constraint ck_qualidade_integracao_tipo check(tipo in ('OUTBOX','DLQ','WEBHOOK','API')), constraint ck_qualidade_integracao_status check(status in ('PENDENTE','CONFORME','FALHA','BLOQUEADO')));

create index if not exists ix_qualidade_inconsistencia_fila on sigov.qualidade_inconsistencia(tenant_id,entidade_id,status,severidade,created_at desc);
create index if not exists ix_qualidade_inconsistencia_modulo on sigov.qualidade_inconsistencia(tenant_id,entidade_id,modulo,created_at desc);
create index if not exists ix_qualidade_inconsistencia_responsavel on sigov.qualidade_inconsistencia(tenant_id,entidade_id,responsavel_usuario_id,status);
create index if not exists ix_qualidade_historico_item on sigov.qualidade_inconsistencia_historico(tenant_id,entidade_id,inconsistencia_id,created_at desc);
create index if not exists ix_qualidade_checklist_contexto on sigov.qualidade_checklist(tenant_id,entidade_id,modulo,status);
create index if not exists ix_qualidade_rota_contexto on sigov.qualidade_smoke_rota(tenant_id,entidade_id,modulo,status);
create index if not exists ix_qualidade_sql_contexto on sigov.qualidade_validacao_sql(tenant_id,entidade_id,status,validado_em desc);

insert into sigov.permissao(chave,descricao,modulo,ativo,created_at)
select chave,nome,'qualidade_sistema',true,now() from(values
 ('QUALIDADE_SISTEMA_DASHBOARD_VIEW','Qualidade: visualizar dashboard'),('QUALIDADE_SISTEMA_CHECKLIST_VIEW','Qualidade: visualizar checklist'),('QUALIDADE_SISTEMA_CHECKLIST_MANAGE','Qualidade: gerenciar checklist'),
 ('QUALIDADE_SISTEMA_INCONSISTENCIA_VIEW','Qualidade: visualizar inconsistências'),('QUALIDADE_SISTEMA_INCONSISTENCIA_MANAGE','Qualidade: gerenciar inconsistências'),('QUALIDADE_SISTEMA_SQL_VIEW','Qualidade: visualizar SQL'),
 ('QUALIDADE_SISTEMA_ROTA_VIEW','Qualidade: visualizar rotas'),('QUALIDADE_SISTEMA_FORMULARIO_VIEW','Qualidade: visualizar formulários'),('QUALIDADE_SISTEMA_PERMISSAO_VIEW','Qualidade: visualizar permissões'),
 ('QUALIDADE_SISTEMA_RELATORIO_EXPORT','Qualidade: exportar relatórios'),('AUDITORIA_CODIGO_VIEW','Auditoria de código: visualizar'),('AUDITORIA_CODIGO_MANAGE','Auditoria de código: gerenciar')) p(chave,nome)
on conflict(chave) do update set descricao=excluded.descricao,modulo=excluded.modulo,ativo=true;
